"""The landing site: site/ is generated by tools/build_site.py from site-src/pages, the README tool tables and the
bundled core skills. A change to any of them must come with the regenerated pages."""

import importlib.util
import json
import os
import re

ROOT = os.path.dirname(os.path.dirname(os.path.abspath(__file__)))


def _builder():
    spec = importlib.util.spec_from_file_location("build_site", os.path.join(ROOT, "tools", "build_site.py"))
    mod = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(mod)
    return mod


def test_site_matches_its_sources():
    b = _builder()
    files = b.build()
    assert b.stale(files) == [], "site/ is out of date: run python tools/build_site.py"


def test_site_lists_every_tool_and_core_skill():
    b = _builder()
    files = b.build()
    home = files["index.html"]
    tools = [t["name"] for g in b.read_tools() for t in g["tools"]]
    assert len(tools) == 58 and len(set(tools)) == len(tools)
    assert all(f'id="t-{t}"' in home for t in tools)
    index = json.loads(files["assets/search.json"])
    assert {e["t"] for e in index if e["g"] == "Tools"} == set(tools)
    assert len([e for e in index if e["g"] == "Skills"]) == len(b.SKILL_TEXT)


def test_site_links_and_assets_resolve():
    b = _builder()
    files = b.build()
    pages = {rel: text for rel, text in files.items() if rel.endswith(".html")}
    ids = {rel: set(re.findall(r'\sid="([^"]+)"', text)) for rel, text in pages.items()}
    for rel, text in pages.items():
        for anchor in re.findall(r'href="#([^"]+)"', text):
            assert anchor in ids[rel], f"{rel}: #{anchor} has no target"
        for path, anchor in re.findall(r'href="(/[^"#?]*)(?:#([^"]+))?"', text):
            target = path.strip("/") + "/index.html" if path.endswith("/") else path.lstrip("/")
            target = target.lstrip("/") or "index.html"
            assert os.path.exists(os.path.join(b.SITE, target)), f"{rel}: {path} does not exist"
            if anchor and target in ids:
                assert anchor in ids[target], f"{rel}: {path}#{anchor} has no target"
        for src in re.findall(r'(?:src|data-zoom|data-zoom-dark|data-anim-src)="(/assets/[^"?]+)', text):
            assert os.path.exists(os.path.join(b.SITE, src.lstrip("/"))), f"{rel}: {src} is missing"
        for srcset in re.findall(r'srcset="([^"]+)"', text):
            for src in re.findall(r"(/assets/\S+)", srcset):
                assert os.path.exists(os.path.join(b.SITE, src.lstrip("/"))), f"{rel}: {src} is missing"
